'use strict';
const $=s=>document.querySelector(s);
const roomData=[{name:'Living Room',icon:'▱',device:'Example media device',on:true,brightness:65},{name:'Kitchen',icon:'♧',device:'Example speaker + sensor',on:true,brightness:80},{name:'Office',icon:'▤',device:'Example speaker + sensor',on:false,brightness:50},{name:'Bathroom',icon:'◒',device:'Example speaker + sensor',on:false,brightness:70},{name:'Home Theater',icon:'▷',device:'Example media device',on:false,brightness:25},{name:'Camera',icon:'◎',device:'Example camera',camera:true}];
const scenes=[{name:'Good morning',icon:'☀',desc:'A brighter beginning'},{name:'Unwind',icon:'☾',desc:'Bring the evening in'},{name:'Movie time',icon:'▷',desc:'Make room for a story'},{name:'Good night',icon:'✧',desc:'Let the house rest'}];
let page='Overview',selectedScene='',activeRoom=null,toastTimer,nativeInventory=null;
try{const saved=JSON.parse(localStorage.getItem('hearth-demo-v1'));if(Array.isArray(saved))roomData.forEach((r,i)=>{if(saved[i]){r.on=Boolean(saved[i].on);r.brightness=Number.isFinite(saved[i].brightness)?Math.max(0,Math.min(100,saved[i].brightness)):r.brightness}})}catch{}
function save(){try{localStorage.setItem('hearth-demo-v1',JSON.stringify(roomData))}catch{}}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function sceneHTML(){return scenes.map((s,i)=>`<button class="scene ${selectedScene===s.name?'selected':''}" data-scene="${i}" aria-pressed="${selectedScene===s.name}"><span class="symbol">${s.icon}</span><span><strong>${s.name}</strong><small>${s.desc}</small></span></button>`).join('')}
function roomsHTML(){return roomData.map((r,i)=>`<article class="room-card"><div class="room-top"><span class="room-symbol">${r.icon}</span>${!r.camera?`<button class="switch" role="switch" aria-label="${r.name} demo light" aria-checked="${r.on}" data-toggle="${i}"></button>`:'<span class="eyebrow">PREVIEW</span>'}</div><button class="room-open" data-room="${i}"><h3>${r.name}</h3><p>${r.camera?r.device:(r.on?'Demo lights on':'Demo lights off')+' · '+r.brightness+'%'}</p><span class="arrow">↗</span></button></article>`).join('')}
function render(){ $('#scenes').innerHTML=sceneHTML();$('#rooms').innerHTML=roomsHTML();$('#overview').hidden=page!=='Overview';$('#page-content').hidden=page==='Overview';$('#heading').textContent=page==='Overview'?'Welcome home.':page==='Devices'?'Your connections.':page==='Scenes'?'Find your moment.':'Room to feel at home.';$('#subtitle').textContent=page==='Overview'?'Your space. Just the way you like it.':page==='Devices'?'A starting point for your connected home.':'Small details. A home that feels like you.';document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.page===page);if(n.dataset.page===page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});
if(page==='Rooms')$('#page-content').innerHTML='<p class="page-intro">Room names are generic examples. Lighting controls and values are examples until Apple Home is connected.</p><div class="room-grid">'+roomsHTML()+'</div>';
if(page==='Scenes')$('#page-content').innerHTML='<p class="page-intro">Try a different atmosphere. These example scenes change this preview only.</p><div class="scene-grid">'+sceneHTML()+'</div>';
if(page==='Devices'){const items=nativeInventory?.homes?.flatMap(h=>h.accessories.map(a=>({name:a.name,detail:h.name+' · '+a.room+' · '+a.services.join(', '),status:a.reachable?'Reachable':'Unavailable'})))||roomData.map(r=>({name:r.name,detail:r.device,status:'Demo example'}));$('#page-content').innerHTML='<p class="page-intro">'+(nativeInventory?'Read-only accessory inventory from Apple Home. Demo room controls remain separate.':'These are generic example devices. Connect Apple Home in the native app to read your own accessory inventory.')+'</p><div class="panel">'+items.map(d=>`<div class="device-row"><div>${escapeHTML(d.name)}<small>${escapeHTML(d.detail)}</small></div><span class="eyebrow">${escapeHTML(d.status)}</span></div>`).join('')+'</div><button class="primary" id="refresh-inventory">Read Apple Home inventory ↗</button>'}}
function showRoom(i){activeRoom=i;const r=roomData[i];$('#room-detail').innerHTML=`<span class="eyebrow">${r.camera?'CAMERA PREVIEW':'ROOM · DEMO CONTROLS'}</span><h2>${r.name}</h2><p>${r.device}</p>`+(r.camera?'<div class="camera-placeholder"><span>◎</span><p>Camera feed is not connected</p></div><p>A real stream requires permission and native camera integration.</p>':`<div class="detail-row"><span>Example room light</span><button class="switch" role="switch" aria-label="${r.name} demo light" aria-checked="${r.on}" data-detail-toggle="${i}"></button></div><label class="detail-label" for="brightness">Brightness <output id="brightness-value">${r.brightness}%</output></label><input id="brightness" type="range" min="0" max="100" value="${r.brightness}" aria-label="Example light brightness"><p>Changes stay in this preview. Your actual accessories are unaffected.</p>`);if(!$('#room-dialog').open)$('#room-dialog').showModal()}
function activateScene(i){selectedScene=scenes[i].name;roomData.filter(r=>!r.camera).forEach((r,j)=>{r.on=i===0||i===1||i===2&&j===4;r.brightness=[85,35,15,0][i]});save();render();toast(selectedScene+' · demo scene applied')}
function connect(){if(window.webkit?.messageHandlers?.homekit){window.webkit.messageHandlers.homekit.postMessage({action:'inventory'});toast('Requesting Apple Home inventory…')}else toast('Open the native iOS app to grant Apple Home access.')}
window.hearthReceiveInventory=function(payload){if(payload.error){toast(payload.error);return}nativeInventory=payload;$('#connection-label').textContent='Home inventory connected';$('#bridge-title').textContent='Your home, connected.';$('#bridge-copy').textContent='The Devices page now shows your Apple Home inventory. Room controls are still a demo.';page='Devices';render();toast('Apple Home inventory received')};
document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.page){page=target.dataset.page;render()}if(target.dataset.scene!==undefined)activateScene(+target.dataset.scene);if(target.dataset.room!==undefined)showRoom(+target.dataset.room);const idx=target.dataset.toggle??target.dataset.detailToggle;if(idx!==undefined){roomData[idx].on=!roomData[idx].on;selectedScene='';save();render();if(target.dataset.detailToggle!==undefined)showRoom(+idx)}if(target.id==='relax')activateScene(1);if(target.id==='night'){document.body.classList.toggle('night');target.setAttribute('aria-pressed',document.body.classList.contains('night'));toast(document.body.classList.contains('night')?'Night view on':'Night view off')}if(['connect','refresh-inventory'].includes(target.id))connect()});
$('#room-detail').addEventListener('input',e=>{if(e.target.id==='brightness'){const r=roomData[activeRoom];r.brightness=+e.target.value;r.on=r.brightness>0;$('#brightness-value').textContent=r.brightness+'%';$('#room-detail .switch').setAttribute('aria-checked',r.on);selectedScene='';save();render()}});
$('.brand').addEventListener('click',e=>{e.preventDefault();page='Overview';render()});$('#room-dialog').addEventListener('click',e=>{if(e.target===$('#room-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function updateTime(){const d=new Date();$('#date').textContent=d.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();$('#clock').textContent=d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}updateTime();setInterval(updateTime,30000);render();
if('serviceWorker'in navigator && ['http:','https:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});
